[2024-12-12T12:41:57Z] user_00116: > Hi @user_00116 , for now, is there a "make install" command for us to get the export include path/library path/ldflags/cflags of matter instead of dealing this by hand or external scripts.

Hello,

As I know: No, I think the equivalent to "make install" does not really exists with GN.

I removed my message, because initialy I was thinking you tried to build the stack with yocto (on your issue), but after re-reading, it was not the case.

So the current build system is not perfect for everyone:
- Due to activate.sh that imply growing requirements (Ubuntu at specific version, python at specific version, etc)
- The GN stuff not providing install/staging.

These restriction are a real pain, when you need to build the stack in a building environment like Yocto/OpenWRT.

As suggested on the top by @user_00017 , currently we do something like this:

```
source scripts/activate.sh

gn gen out/host --args='treat_warnings_as_errors=false chip_use_data_model_interface="enabled" chip_enable_wifi=false chip_enable_python_modules=false chip_enable_ble=false chip_config_network_layer_ble=false chip_enable_openthread=false config_enable_yaml_tests=false chip_build_tests=false chip_build_test_static_libraries=false'

ninja -C out/host

gn desc out/host '*' --format=json > /tmp/matter.json
```

And then we parse /tmp/matter.json with a python script to generate CMake Libs that we need.

The generating scripts looks something like this:

```
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import functools
import json
import os
import shutil
import sys

dependencies_dict = {}
existing_dependencies = {}
repo_dir = ""  # For example: /mnt/project/git/PUBLIC/connectedhomeip/
output_dir = ""  # For example: ./src/libraries/Matter/
stack_sources_subdir = "/Stack/"
stack_sources_dir = "${CMAKE_CURRENT_SOURCE_DIR}/../" + stack_sources_subdir
version = "1.4.0.0"


def is_header(filename):
    return filename.endswith(".h") or filename.endswith(".hpp")


def is_source(filename):
    return filename.endswith(".c") or filename.endswith(".cpp")


def public_headers(target):
    if target["public"] != "*":
        return target["public"]
    return filter(is_header, target.get("sources", []))


def sources(target):
    return filter(is_source, target.get("sources", []))


def defines(target):
    return target.get("defines", [])


def cflags(target):
    return target.get("cflags", [])


def cflags_cc(target):
    return target.get("cflags_cc", [])


def cflags_c(target):
    return target.get("cflags_c", [])


def include_dirs(target):
    return target.get("include_dirs", [])


def libs(target):
    return target.get("libs", [])


def deps(target):
    return target.get("deps", [])


def get_all_dependencies():
    return {item for sublist in dependencies_dict.values() for item in sublist}


@functools.lru_cache
def transitive_headers(target) -> set:
    target_json = gn_json[target]
    return set(public_headers(target_json)).union(
        *[transitive_headers(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_sources(target) -> set:
    target_json = gn_json[target]
    return set(sources(target_json)).union(
        *[transitive_sources(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_defines(target) -> set:
    global existing_dependencies
    target_json = gn_json[target]
    return set(defines(target_json)).union(
        *[transitive_defines(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_cflags(target) -> set:
    target_json = gn_json[target]
    return set(cflags(target_json)).union(
        *[transitive_cflags(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_include_dirs(target) -> set:
    target_json = gn_json[target]
    return set(include_dirs(target_json)).union(
        *[transitive_include_dirs(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_cflags_cc(target) -> set:
    target_json = gn_json[target]
    return set(cflags_cc(target_json)).union(
        *[transitive_cflags_cc(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_cflags_c(target) -> set:
    target_json = gn_json[target]
    return set(cflags_c(target_json)).union(
        *[transitive_cflags_c(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_libs(target) -> set:
    target_json = gn_json[target]
    return set(libs(target_json)).union(
        *[transitive_libs(public_dep) for public_dep in target_json.get("deps", []) if
          public_dep not in existing_dependencies]
    )


@functools.lru_cache
def transitive_deps(target) -> set:
    target_json = gn_json[target]
    return set(deps(target_json)).union(
        *[transitive_deps(public_dep) for public_dep in target_json.get("deps", [])]
    )


def convert_gn_filename(filename, base_path=stack_sources_dir):
    if filename.startswith("//"):
        return filename.replace("//", base_path)
    return filename


def generate_cmakelists(defines_list, headers_list, sources_list, cflags_list, cflags_c_list, cflags_cc_list,
                        include_dirs_list, libs_list, lib_name, lib_version, output_file="CMakeLists.txt"):
    os.makedirs(os.path.dirname(output_file), exist_ok=True)

    with open(output_file, "w") as cmake_file:
        cmake_file.write("cmake_minimum_required(VERSION 3.15)\n\n")

        cmake_file.write(f"set(namespace \"{lib_name}\")\n")
        cmake_file.write(f"project({lib_name} VERSION {lib_version} DESCRIPTION \"Matter Stack\")\n\n")

        cmake_file.write(f"if (NOT CMAKE_PROJECT_NAME STREQUAL PROJECT_NAME)\n")
        cmake_file.write(
            "    message(STATUS \"The project '${PROJECT_NAME}' is included in the top-level project called '${CMAKE_PROJECT_NAME}'\")\n")
        cmake_file.write("else()\n")
        cmake_file.write("    message(STATUS \"The project '${PROJECT_NAME}' is a top-level project\")\n")
        cmake_file.write("endif()\n\n")

        cmake_file.write(f"set(CMAKE_CXX_STANDARD 17)\n")
        cmake_file.write(f"set(CMAKE_CXX_STANDARD_REQUIRED ON)\n")

        cmake_file.write("add_library(${PROJECT_NAME} STATIC)\n")

        cmake_file.write("set(CMAKE_C_FLAGS \"${CMAKE_C_FLAGS} ")
        for flag in cflags_c_list:
            cmake_file.write(f"{flag} ")
        cmake_file.write("\")\n\n")

        cmake_file.write("set(CMAKE_CXX_FLAGS \"${CMAKE_CXX_FLAGS} ")
        for flag in cflags_cc_list:
            cmake_file.write(f"{flag} ")
        cmake_file.write("\")\n\n")

        cmake_file.write("set(SOURCES\n")
        for file in sources_list:
            cmake_file.write(f"    {convert_gn_filename(file)}\n")
        cmake_file.write(")\n\n")

        cmake_file.write("set(HEADERS\n")
        for file in headers_list:
            cmake_file.write(f"    {convert_gn_filename(file)}\n")
        cmake_file.write(")\n\n")

        cmake_file.write("target_sources(${PROJECT_NAME} PRIVATE ${SOURCES} ${HEADERS})\n")

        cmake_file.write("target_include_directories(${PROJECT_NAME} PRIVATE\n")
        for file in include_dirs_list:
            cmake_file.write(f"    {convert_gn_filename(file)}\n")
        cmake_file.write(")\n\n")

        cmake_file.write("target_compile_options(${PROJECT_NAME} PRIVATE\n")
        for define in defines_list:
            cmake_file.write(f"    -D{define}\n")
        cmake_file.write(")\n\n")

        cmake_file.write("target_compile_options(${PROJECT_NAME} PRIVATE\n")
        for flag in cflags_list:
            cmake_file.write(f"    {flag}\n")
        cmake_file.write(")\n\n")

        cmake_file.write("target_link_libraries(${PROJECT_NAME} PRIVATE\n")
        for lib in libs_list:
            cmake_file.write(f"    {lib}\n")
        cmake_file.write(")\n\n")

        cmake_file.write("set(CMAKE_MODULE_PATH \"${CMAKE_CURRENT_SOURCE_DIR}/cmake\")\n")
        cmake_file.write("include(Installing)\n")

    print(f"CMakeLists.txt généré dans : {output_file}")


def generate_target_cmakelists(target, lib_name, lib_version, out_dir):
    # Get all the dependencies already solved
    global existing_dependencies
    existing_dependencies = get_all_dependencies()

    # Read all the dependencies (recursively) of the current target
    dependencies = transitive_deps(target)

    # Create a list that will store the previous "target/libraries" that will be appended to the libs of the current target
    extra_libs_list = list()
    for lib in dependencies_dict:
        if any(x in dependencies_dict[lib] for x in dependencies):
            extra_libs_list.append(lib)

    # Add the "target" to the dependencies list of the current target
    dependencies.add(target)

    # Cleanup the list that store the previous "target/libraries" to add in the libs.
    for lib in extra_libs_list:
        for dep in dependencies_dict[lib]:
            if dep in dependencies:
                dependencies.remove(dep)
    dependencies_dict[lib_name] = sorted(dependencies)

    #######################################
    # Generate the different lists
    #######################################
    defines_list = sorted(transitive_defines(target))
    headers_list = sorted(transitive_headers(target))
    sources_list = sorted(transitive_sources(target))
    cflags_list = sorted(transitive_cflags(target))
    cflags_c_list = sorted(transitive_cflags_c(target))
    cflags_cc_list = sorted(transitive_cflags_cc(target))
    include_dirs_list = sorted(transitive_include_dirs(target))
    libs_list = sorted(transitive_libs(target))

    include_dirs_list.append(stack_sources_dir)

    # Add in the libs list of the target, the previous targets used as libraries
    for x in extra_libs_list:
        libs_list.append(x)

    #######################################
    # Replace some information's
    #######################################
    if "-Wconversion" in cflags_list:
        cflags_list[cflags_list.index("-Wconversion")] = "-Wno-conversion"
    if "-Werror" in cflags_list:
        cflags_list[cflags_list.index("-Werror")] = "-Wno-error"

    # Add some extra files to take for the export
    include_dirs_list.append(stack_sources_dir + "third_party/nlassert/repo/include")

    #######################################
    # Generate CMakeList.txt
    #######################################
    generate_cmakelists(defines_list, headers_list, sources_list, cflags_list, cflags_c_list, cflags_cc_list,
                        include_dirs_list, libs_list, lib_name, lib_version, out_dir + f"/{lib_name}/CMakeLists.txt")


def export_stack_dir(path: str):
    os.makedirs(output_dir + stack_sources_subdir + path, exist_ok=True)
    export_input_dir = repo_dir + "/" + path
    export_output_dir = output_dir + "/" + stack_sources_subdir + path
    copy_cpp_hpp_files(export_input_dir, export_output_dir)


def copy_cpp_hpp_files(src_dir: str, dest_dir: str):
    for root, _, files in os.walk(src_dir):
        for file in files:
            if file.endswith(('.cpp', '.hpp', '.ipp', '.c', '.h', '.inl')):
                src_file = os.path.join(root, file)
                relative_path = os.path.relpath(root, src_dir)
                dest_subdir = os.path.join(dest_dir, relative_path)
                os.makedirs(dest_subdir, exist_ok=True)
                shutil.copy2(src_file, dest_subdir)
                print(f"Copié: {src_file} -> {os.path.join(dest_subdir, file)}")


def export_stack():
    export_stack_dir("third_party/inipp")
    export_stack_dir("third_party/jsoncpp")
    export_stack_dir("third_party/nlassert")
    export_stack_dir("third_party/nlfaultinjection")
    export_stack_dir("third_party/nlio")
    export_stack_dir("zzz_generated/app-common")
    export_stack_dir("src")
    export_stack_dir("out/host/gen/include")
    export_stack_dir("out/host/gen/src")


def usage():
    print("Usage:")
    print(f"{sys.argv[0]} [path to matter.json] [path to connectedhomeip repository] [path to export files]")


if __name__ == '__main__':
    args = sys.argv[1:]

    if len(args) != 3:
        usage()
        exit(0)

    gn_json = json.loads(open(args[0]).read())
    repo_dir = args[1]
    output_dir = args[2]

    generate_target_cmakelists("//src/lib:lib", "Matter", version, output_dir)
    generate_target_cmakelists("//src/controller/data_model:data_model", "MatterDataModel", version,
                               output_dir)
    generate_target_cmakelists("//src/lib/support:test_utils", "MatterTestUtils", version,
                               output_dir)
    generate_target_cmakelists("//src/app/tests/suites/commands/interaction_model:interaction_model",
                               "MatterInteractionModel", version, output_dir)
    generate_target_cmakelists("//src/lib/support/jsontlv:jsontlv", "JsonTLV", version,
                               output_dir)

    # Export the stack to "output_dir + stack_sources_subdir"
    export_stack()
```

Usage example:
```
./script/export_matter_stack.py /tmp/matter.json /mnt/project/git/PUBLIC/connectedhomeip/ ./src/libraries/Matter
```

This is maybe not optimal.


