 #### cpp file ：

~~~cpp

#include "ValidateKeypairCommand.h"
#include "Keypair.h"
#include <assert.h>
#include <lib/core/CHIPError.h>

using namespace ::chip::Credentials;

CHIP_ERROR ValidateKeypairCommand::Run()
{
    system("clear");

    Crypto::P256ECDSASignature signature;
    MutableByteSpan signatureByPrivateKey{ signature.Bytes(), signature.Capacity() };

    this->SignByPrivateKey(signatureByPrivateKey);

    this->ValidateByPublicKey(signatureByPrivateKey);

    return CHIP_NO_ERROR;
}

void ValidateKeypairCommand::SignByPrivateKey(MutableByteSpan & signatureByPrivateKey)
{
    // message_to_sign
    uint8_t md[Crypto::kSHA256_Hash_Length];
    MutableByteSpan message_to_sign(md);
    MessageToSignature(message_to_sign);

    // keypair
    Crypto::P256Keypair keypair;
    assert(LoadKeypairFromRaw(Haier::Keypair::kDacPriKey, Haier::Keypair::kDacPubKey, keypair) == CHIP_NO_ERROR);

    // signature
    Crypto::P256ECDSASignature signature;
    assert(keypair.ECDSA_sign_msg(message_to_sign.data(), message_to_sign.size(), signature) == CHIP_NO_ERROR);

    assert(CopySpanToMutableSpan(ByteSpan{ signature.ConstBytes(), signature.Length() }, signatureByPrivateKey) == CHIP_NO_ERROR);

    assert(signatureByPrivateKey.size() == Crypto::P256ECDSASignature::Capacity());
}

void ValidateKeypairCommand::ValidateByPublicKey(MutableByteSpan & signatureByPrivateKey)
{
    // public key
    P256PublicKey pubkey;
    assert(ExtractPubkeyFromX509Cert(Haier::Keypair::kDacCert, pubkey) == CHIP_NO_ERROR);

    // signatureByPrivateKey - > deviceSignature
    P256ECDSASignature deviceSignature;
    assert(deviceSignature.SetLength(signatureByPrivateKey.size()) == CHIP_NO_ERROR);
    memcpy(deviceSignature.Bytes(), signatureByPrivateKey.data(), signatureByPrivateKey.size());

    // message_to_signature
    uint8_t md[kSHA256_Hash_Length];
    MutableByteSpan message_to_signature(md);
    MessageToSignature(message_to_signature);

    // validate
    // error here : Assertion `pubkey.ECDSA_validate_hash_signature(message_to_signature.data(), message_to_signature.size(),
    // deviceSignature) == CHIP_NO_ERROR' failed.
    assert(pubkey.ECDSA_validate_hash_signature(message_to_signature.data(), message_to_signature.size(), deviceSignature) ==
           CHIP_NO_ERROR);
}

CHIP_ERROR LoadKeypairFromRaw(ByteSpan private_key, ByteSpan public_key, Crypto::P256Keypair & keypair)
{
    Crypto::P256SerializedKeypair serialized_keypair;
    ReturnErrorOnFailure(serialized_keypair.SetLength(private_key.size() + public_key.size()));
    memcpy(serialized_keypair.Bytes(), public_key.data(), public_key.size());
    memcpy(serialized_keypair.Bytes() + public_key.size(), private_key.data(), private_key.size());
    return keypair.Deserialize(serialized_keypair);
}

void MessageToSignature(MutableByteSpan & messageDigestSpan)
{
    Hash_SHA256_stream hashStream;
    assert(hashStream.Begin() == CHIP_NO_ERROR);
    assert(hashStream.AddData(Haier::Keypair::kAttestationElements) == CHIP_NO_ERROR);
    assert(hashStream.AddData(Haier::Keypair::kAttestationChallenge) == CHIP_NO_ERROR);
    assert(hashStream.Finish(messageDigestSpan) == CHIP_NO_ERROR);
}

~~~

