```c
void AppTask::UpdateCluster(intptr_t context)
{
    uint8_t newOnOffState = !LockMgr().NextState();
    EmberAfStatus OnOffstatus =
        emberAfWriteAttribute(1, ZCL_ON_OFF_CLUSTER_ID, ZCL_ON_OFF_ATTRIBUTE_ID, (uint8_t *) &newOnOffState, ZCL_BOOLEAN_ATTRIBUTE_TYPE);

    if (OnOffstatus != EMBER_ZCL_STATUS_SUCCESS)
    {
        P6_LOG("ERR: updating lock state %x", OnOffstatus);
    }
}
```
2. `ZCL_ON_OFF_ATRRIBUTE` -> LED
[https://github.com/project-chip/connectedhomeip/blob/0b17bce8005fb155e78e243f31111cdaf2c92797/examples/lock-app/infineon/psoc6/src/ZclCallbacks.cpp#L37](https://github.com/project-chip/connectedhomeip/blob/0b17bce8005fb155e78e243f31111cdaf2c92797/examples/lock-app/infineon/psoc6/src/ZclCallbacks.cpp#L37)

```c
void MatterPostAttributeChangeCallback(const chip::app::ConcreteAttributePath & attributePath, uint8_t type, uint16_t size,
                                       uint8_t * value)
{
    EndpointId endpointId   = attributePath.mEndpointId;
    ClusterId clusterId     = attributePath.mClusterId;
    AttributeId attributeId = attributePath.mAttributeId;
    ChipLogProgress(Zcl, "Cluster callback: " ChipLogFormatMEI, ChipLogValueMEI(clusterId));

    if (clusterId == DoorLock::Id && attributeId == DoorLock::Attributes::LockState::Id)
    {
        ChipLogProgress(Zcl, "Door lock cluster: " ChipLogFormatMEI, ChipLogValueMEI(clusterId));
    }

    if (clusterId == ZCL_ON_OFF_CLUSTER_ID)
    {
        OnOnOffPostAttributeChangeCallback(endpointId, attributeId, value);
    }
}

// add below callback
void OnOnOffPostAttributeChangeCallback(EndpointId endpointId, AttributeId attributeId, uint8_t * value)
{
    VerifyOrExit(attributeId == ZCL_ON_OFF_ATTRIBUTE_ID, ChipLogProgress(Zcl, "Unhandled Attribute ID: '0x%04x", (int)attributeId));
    VerifyOrExit(endpointId == 1 , ChipLogProgress(Zcl, "Unexpected EndPoint ID: `0x%02x'", (int)endpointId));
    if (*value)
    {
        LockMgr().InitiateAction(AppEvent::kEventType_Lock, LockManager::LOCK_ACTION);
    }
    else
    {
        LockMgr().InitiateAction(AppEvent::kEventType_Lock, LockManager::UNLOCK_ACTION);
    }
exit:
    return;
}

```



