can you help me?


EmberAfStatus emberAfExternalAttributeWriteCallback(EndpointId endpoint, ClusterId clusterId,
																										const EmberAfAttributeMetadata *attributeMetadata, uint8_t *buffer)
{
	uint16_t endpointIndex = emberAfGetDynamicIndexFromEndpoint(endpoint);

	if (endpointIndex < CHIP_DEVICE_CONFIG_DYNAMIC_ENDPOINT_COUNT)
	{
		Accessory *accessory = accessories[endpointIndex];

		if ((accessory->IsReachable()) && (clusterId == ZCL_ON_OFF_CLUSTER_ID))
		{
			printf("write ZCL_ON_OFF_CLUSTER_ID %d\n", *buffer);
			accessory->SetOn(*buffer == 1);
			return EMBER_ZCL_STATUS_SUCCESS;
		}

		if ((accessory->IsReachable()) && (clusterId == ZCL_LEVEL_CONTROL_CLUSTER_ID))
		{
			if ((attributeMetadata->attributeId == ZCL_CURRENT_LEVEL_ATTRIBUTE_ID))
			{
				printf("write ZCL_LEVEL_CONTROL_CLUSTER_ID %d\n", *buffer);
				accessory->SetLevel(buffer);
			}
			else
			{
				return EMBER_ZCL_STATUS_FAILURE;
			}
			return EMBER_ZCL_STATUS_SUCCESS;
		}
	}

	return EMBER_ZCL_STATUS_FAILURE;
}

