[2022-12-23T12:54:04Z] user_00531: I added `ScheduleReportingCallback` from `bridge-app` and that resolved the issue

```
namespace {
    void CallReportingCallback(intptr_t closure)
    {
        auto path = reinterpret_cast<app::ConcreteAttributePath *>(closure);
        MatterReportingAttributeChangeCallback(*path);
        Platform::Delete(path);
    }

    void ScheduleReportingCallback(Device * dev, ClusterId cluster, AttributeId attribute)
    {
        ChipLogProgress(DeviceLayer, "Report attribute change %d - %d - %d", dev->GetEndpointId(), cluster, attribute);

        auto * path = Platform::New<app::ConcreteAttributePath>(dev->GetEndpointId(), cluster, attribute);
        DeviceLayer::PlatformMgr().ScheduleWork(CallReportingCallback, reinterpret_cast<intptr_t>(path));
    }
}
```

