    DECLARE_DYNAMIC_CLUSTER(chip::app::Clusters::BridgedDeviceBasic::Id, bridgedDeviceBasicAttrs, nullptr, nullptr) DECLARE_DYNAMIC_CLUSTER_LIST_END;

