[2023-06-02T17:42:39Z] user_00314: Hi @user_00012 ,

1. I have attached the files [MTRCSRKeys.zip](https://github.com/project-chip/connectedhomeip/files/11637701/MTRCSRKeys.zip)  for the class ```MTRCSRKeys``` used to create keypair. You can check the ```- (instancetype)initWithGroupId:(NSString *) grpId``` method to get the steps used to create the keypair. 
2. The method ```- (NSData *)publicKeyData``` is for the ```publickey``` implementation.
3. The method ```- (NSData *)signMessageECDSA_DER:(NSData *)message``` contains implementation for signing a message. 
I have reused the implementation of the ```FabrickKeys``` class from the CHIP repo for implementing the class.

For the commissioning I am using the following code:

- Initialise matter controller:
```
    func initializeMTRControllerWithUserNOC(matterFabricData: ESPNodeGroup, userNOCData: ESPIssueUserNOCResponse) {
        let storage = ESPMatterStorage.shared
        let factory = MTRDeviceControllerFactory.sharedInstance()
        let factoryParams = MTRDeviceControllerFactoryParams(storage: storage)
        if let _ = matterFabricData.fabricID?.hexToDecimal {
            do {
                try factory.start(factoryParams)
            } catch {
                return
            }
            if let grpId = group?.groupID {
                let keys = MTRCSRKeys(groupId: grpId)
                if let details = matterFabricData.fabricDetails, let rootCA = details.rootCACertificate, let rootCADerBytes = MTRCertificates.convertPEMString(toDER: rootCA), let certs = userNOCData.certificates, certs.count > 0, let noc = certs[0].userNOC, let nocDerBytes = MTRCertificates.convertPEMString(toDER: noc) {
                    let params = MTRDeviceControllerStartupParams(ipk: keys.ipk, ——> returned by the MTRCSRKeys NSData * ipk 
                        operationalKeypair: keys,   ——> MTRCSRKeys instance
                        operationalCertificate: nocDerBytes, ——> returned by cloud
                        intermediateCertificate: nil, 
                        rootCertificate: rootCADerBytes) ——-> created by cloud on fabric creation
                    params.vendorID = NSNumber(value: kTestVendorId)
                    params.operationalCertificateIssuer = self
                    params.operationalCertificateIssuerQueue = DispatchQueue.main
                    if let controller = try? factory.createController(onNewFabric: params) {
                        sController = controller
                        sController?.setDeviceControllerDelegate(self, queue: self.matterQueue)
                    } else if let controller = try? factory.createController(onExistingFabric: params) {
                        sController = controller
                        sController?.setDeviceControllerDelegate(self, queue: self.matterQueue)
                    }
                    return
                }
            }
        }
    }
```
- Start commissioning:
```
    /// Start commissioning with user NOC
    /// - Parameters:
    ///   - onboardingPayload: onboarding payload
    ///   - deviceId: device id
    func startCommissioningWithUserNOC(onboardingPayload: String, deviceId: UInt64) {
        if let controller = sController, let payload = try? MTRSetupPayload(onboardingPayload: onboardingPayload) {
            do {
                try controller.setupCommissioningSession(with: payload, newNodeID: NSNumber(value: deviceId))
                if let group = self.group, let groupName = group.groupName, let deviceName = ESPMatterEcosystemInfo.shared.getDeviceName() {
                    self.uidelegate?.showLoaderInView(message: "Commissioning \(deviceName) to \(groupName)")
                }
            }
            catch {
                print("ERROR pairAccessory: \(error.localizedDescription)")
            }
        }
    }
```
- Continue commissioning after commissioning session is established:
```
    func controller(_ : MTRDeviceController, commissioningSessionEstablishmentDone error: Error?) {
        guard let _ = error else {
            let deviceId = ESPMatterDeviceManager.shared.getCurrentDeviceId()
            let params = MTRCommissioningParameters()
            params.deviceAttestationDelegate = self
            if let controller = sController {
                do {
                    try controller.commissionNode(withID: NSNumber(value: deviceId), commissioningParams: params)
                } catch {
                    print(error.localizedDescription)
                }
            }
            return
        }
        self.hideLoaderAndShowFailure(title: "Failure", message: "Failed to pair device.", buttonTitle: ESPMatterConstants.okTxt)
    }
```
- After device attestation callbacks are invoked we call the ```continueCommissioningDevice``` API.
- Next callbacks are the ```MTROperationalCertificateIssuer``` callbacks:

```
/// NOC Chain issuer
extension ESPMTRCommissioner: MTROperationalCertificateIssuer {
    
    /// should skip attestation
    var shouldSkipAttestationCertificateValidation: Bool {
        return true
    }
    
    /// Issue operational certificate
    /// - Parameters:
    ///   - csrInfo: CSR info
    ///   - attestationInfo: attestation info
    ///   - controller: controller
    ///   - completion: completion
    func issueOperationalCertificate(forRequest csrInfo: MTROperationalCSRInfo, attestationInfo: MTRDeviceAttestationInfo, controller: MTRDeviceController, completion: @escaping (MTROperationalCertificateChain?, Error?) -> Void) {
        self.completion = completion
        let csrData = csrInfo.csrElementsTLV
        if let group = group, let groupId = group.groupID, let csrString = MTRCertificates.deconstructNOCSRElements(csrData) {
            self.getDeviceMetaData { metadata in
                let nodeGroupURL = Configuration.shared.awsConfiguration.baseURL + "/" + Constants.apiVersion
                let service = ESPAddNodeToMatterFabricService(presenter: self)
                let finalCSR = "-----BEGIN CERTIFICATE REQUEST-----\n\(csrString)\n-----END CERTIFICATE REQUEST-----"

                /*
                Note: addNodeToMatterFabric retrieves Node NOC from cloud and pass that in the completion callback.
                */

                if let metadata = metadata, metadata.count > 0 {
                    service.addNodeToMatterFabric(url: nodeGroupURL, groupId: groupId, operation: "add", csr: finalCSR, metadata: metadata)
                } else {
                    service.addNodeToMatterFabric(url: nodeGroupURL, groupId: groupId, operation: "add", csr: finalCSR, metadata: nil)
                }
            }
        }
    }


    /// Node NOC received from cloud
    /// - Parameters:
    ///   - groupId: group id
    ///   - response: response
    ///   - error: error
    func nodeNOCReceived(groupId: String, response: ESPAddNodeToFabricResponse?, error: Error?) {
        let deviceId = ESPMatterDeviceManager.shared.getCurrentDeviceId()
        if let completion = completion, let response = response {
            ESPMatterFabricDetails.shared.saveAddNodeToMatterFabricDetails(groupId: groupId, deviceId: deviceId, data: response)
            if let data = ESPMatterFabricDetails.shared.getAddNodeToMatterFabricDetails(groupId: groupId, deviceId: deviceId), let certs = data.certificates, certs.count > 0, let noc = certs[0].nodeNOC, let nocData = MTRCertificates.convertPEMString(toDER: noc), let fabricData = group?.fabricDetails, let rootCACert = fabricData.rootCACertificate, let rootCertData = MTRCertificates.convertPEMString(toDER: rootCACert) {        
                if let fabData = group?.fabricDetails, let catIdAdmin = fabData.catIdAdmin, let id = "FFFFFFFD\(catIdAdmin)".hexToDecimal {
                    let params = MTROperationalCertificateChain(operationalCertificate: nocData, intermediateCertificate: nil, rootCertificate: rootCertData, adminSubject: NSNumber(value: id))
                    completion(params, nil)
                }
            }
        }
    }
}
```

