[2023-07-25T14:59:29Z] user_00012: `GetClusterId()` is a static function in the codegen bits, but the code calling it does not assume it's static.  It's called like so:
```
aEventData.GetClusterId()
```
via templated code where aEventData is some concrete type that we are templated over.

So I think you should be able to do something like:
```
    class GenericErrorEvent : private app::Clusters::OperationalState::Events::OperationalError::Type 
    {
        using super = app::Clusters::OperationalState::Events::OperationalError::Type;
    public:
        GenericErrorEvent(ClusterId aClusterId, const Structs::ErrorStateStruct::Type & aError) : mClusterId(aClusterId), errorState(aError) {} 
        using super::GetPriorityLevel
        using super::GetEventId;
        ClusterId GetClusterId() const { return mClusterId; }
        using super::kIsFabricScoped;
        using super::Encode;
    private:
       ClusterId mClusterId;
    };
```

