# By the way we read the publicKey from certificate signing request(csr), can you implement one for 16.1-16.4, 

like 

```
+ (SecKeyRef)publicKeyFromCSRTP:(MTRCSRDERBytes)csr
                          error:(NSError * __autoreleasing _Nullable * _Nullable)error
{
    SecKeyRef operationalPublicKey = NULL;
    if (@available(iOS MatterSupportVersion16_4, *))
    {
        NSError * error = nil;
        NSData *iotPublicKeyData = [MTRCertificates publicKeyFromCSR:csr
                                                               error:&error];
        NSDictionary * attributes = @{
            (__bridge id) kSecAttrKeyType : (__bridge id) kSecAttrKeyTypeECSECPrimeRandom,
            (__bridge id) kSecAttrKeyClass : (__bridge id) kSecAttrKeyClassPublic
        };
        CFErrorRef keyCreationError = NULL;
        operationalPublicKey = SecKeyCreateWithData((__bridge CFDataRef) iotPublicKeyData, 
                                   (__bridge CFDictionaryRef) attributes,
                                   &keyCreationError);
    }
    else if (@available(iOS MatterSupportVersion16_1, *))
    {
        operationalPublicKey = [self getPublicKeyFromCSR:csr error:error]];
    }
    
    return operationalPublicKey;
}

+ (SecKeyRef)getPublicKeyFromCSR:(NSData *)csr error:(NSError * __autoreleasing _Nullable * _Nullable)error
{

    //    csr = [[NSData alloc] initWithBase64EncodedString:@"MIHLMHACAQAwDjEMMAoGA1UECgwDQ1NSMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEfvpznRVPWBx5YJ+3eoV0TC1x6oN1PGAU4vipSZtOMh5wnwAm1SnBWQx7bfFLag6dtFCnv122jsmhmiNqxOL1/KAAMAwGCCqGSM49BAMCBQADSQAwRgIhAMgx2J9P3tbL7DpFxRNzwwMntwxUWBzBsRXrNUL+br8qAiEAntN57owtMkJIWbN9y1d+E64AZuV72dxSBySvbkWvEIA=" options:0];
    VerifyOrReturnValue(csr.length == 0, nil, [self setError:error msg:@"csr length 0❌"]);
    
    const unsigned char * csrData = csr.bytes;
    X509_REQ *x509Req = d2i_X509_REQ(NULL, &(csrData), csr.length);
    VerifyOrReturnValue(x509Req != NULL, nil, [self setError:error msg:@"d2i_X509_REQ failed❌"]);
    
    EVP_PKEY *pKey = X509_REQ_get_pubkey(x509Req);
    VerifyOrReturnValue(pKey != NULL, nil, [self setError:error msg:@"X509_REQ_get_pubkey failed❌"]);
    
    EC_KEY *ecKey = EVP_PKEY_get1_EC_KEY(pKey);
    VerifyOrReturnValue(ecKey != NULL, nil, [self setError:error msg:@"EVP_PKEY_get1_EC_KEY failed❌"]);
    
    const EC_GROUP* ecGroup = EC_KEY_get0_group(ecKey);
    VerifyOrReturnValue(ecGroup != NULL, nil, [self setError:error msg:@"EC_KEY_get0_group failed❌"]);
    
    const EC_POINT * pubkey_ecp = EC_KEY_get0_public_key(ecKey);
    VerifyOrReturnValue(pubkey_ecp != NULL, nil, [self setError:error msg:@"EC_KEY_get0_public_key failed❌"]);
    
    size_t pubKeyLen = EC_POINT_point2oct(ecGroup, pubkey_ecp, POINT_CONVERSION_UNCOMPRESSED, NULL, 0, NULL);
    
    unsigned char *publicKeyData = malloc(pubKeyLen);
    
    EC_POINT_point2oct(ecGroup, pubkey_ecp, POINT_CONVERSION_UNCOMPRESSED, publicKeyData, pubKeyLen, NULL);
    NSData *publicKeyBytes = [NSData dataWithBytesNoCopy:publicKeyData length:pubKeyLen];
    VerifyOrReturnValue(publicKeyBytes != NULL, nil, [self setError:error msg:@"dataWithBytesNoCopy failed❌"]);

    NSDictionary *attr = @{
        (__bridge id)kSecAttrKeyType: (__bridge id)kSecAttrKeyTypeECSECPrimeRandom,
        (__bridge id)kSecAttrKeyClass: (__bridge id)kSecAttrKeyClassPublic
    };
    CFErrorRef innerError = NULL;
    SecKeyRef publicKeyRef = SecKeyCreateWithData((__bridge CFDataRef)publicKeyBytes, (__bridge CFDictionaryRef)attr, &innerError);

    EVP_PKEY_free(pKey);

    return publicKeyRef;
}

+(void)setError:(NSError * __autoreleasing _Nullable * _Nullable)error msg:(NSString *)msg
{
    if (error)
    {    
        *error = [NSError errorWithDomain:MatterErrorDomain code:MATTER_ERROR_INTERNAL userInfo:@{MatterErrorMessage: msg}];
    }
    MTRLog(@"%@", msg);
}
