        {
            os_log(.default, "FAGAN: commissioningSessionEstablishmentDone->\(error!.localizedDescription)")
        }
    }
    
    func controller(_ controller: MTRDeviceController, commissioningComplete error: Error?)
    {
        os_log(.default, "FAGAN: commissioningComplete")
        
        if (error != nil)
        {
            os_log(.error, "FAGAN: commissioningComplete ERROR->\(error!.localizedDescription)")
        }
    }
    
    func createMatterController() -> MTRDeviceController?
    {
        let storage = MatterStorage.shared
        let factory = MTRDeviceControllerFactory.sharedInstance()
        let factoryParams = MTRDeviceControllerFactoryParams(storage: storage)
        
        do
        {
            try factory.start(factoryParams)
        }
        catch
        {
            os_log(.default, "FAGAN: unable to start factory")
            return nil
        }
        
        let keys = FabricKeys()
        
        // OLD WAY
        os_log(.default, "FAGAN: MTRDeviceControllerStartupParams OLD WAY")
        let params = MTRDeviceControllerStartupParams(signing: keys, fabricId: UInt64(fabricId), ipk: keys.ipk)
        // NEW WAY
        //        os_log(.default, "FAGAN: MTRDeviceControllerStartupParams NEW WAY")
        //        let params = MTRDeviceControllerStartupParams(ipk: keys.ipk, fabricID: NSNumber(value: fabricId), nocSigner: keys)
        
        params.vendorID = NSNumber(value: self.vendorId)
        
        os_log(.default, "FAGAN: create controller on Existing Fabric")
        var matterController = try? factory.createController(onExistingFabric: params)
        
        if (matterController == nil)
        {
            os_log(.default, "FAGAN: create controller on New Fabric")
            matterController = try? factory.createController(onNewFabric: params)
        }
        
        let callbackQueue = DispatchQueue(label: "com.bhtronics.pairing.callback")
        matterController?.setDeviceControllerDelegate(self, queue: callbackQueue)
        
        return matterController
    }
    
    func commission()
    {
        let params = MTRCommissioningParameters()
        
        do
        {
            guard self.matterController != nil else
            {
                os_log(.default, "FAGAN: commission->matterController is null")
                return
            }
            
            os_log(.default, "FAGAN: commissionNode(\(self.deviceNid))")
            
            try self.matterController!.commissionNode(withID: NSNumber(value: self.deviceNid), commissioningParams: params)
        }
        catch let error
        {
            os_log(.error, "FAGAN: commissionNode exception->\(error.localizedDescription)")
        }
    }
}

extension RequestHandler
{

}

```





