[2023-11-21T19:15:54Z] user_00134: The bug is that ParseCommissioningInfo2 is looking for the ICD cluster attribute even when it was not requested (eg. because params.GetICDRegistrationStrategy() != ICDRegistrationStrategy::kIgnore.

Here is the code which has the bug (along with my workaround to confirm its the source of the problem):



void DeviceCommissioner::ParseCommissioningInfo2()
{
    ReadCommissioningInfo2 info;
    CHIP_ERROR return_err = CHIP_NO_ERROR;

    return_err = ParseFabrics(info);

    if (return_err == CHIP_NO_ERROR)
    {
        return_err = ParseICDInfo(info);
        // BUG is that above check returns error when the ICD attribute was not fetched
        if (return_err == CHIP_ERROR_KEY_NOT_FOUND)
        {
            // did not get key, ignore
            return_err = CHIP_NO_ERROR;
        }
    }

    CommissioningDelegate::CommissioningReport report;
    report.Set<ReadCommissioningInfo2>(info);
    CommissioningStageComplete(return_err, report);
}


