I call method `MTRGetConnectedDevice`

```
func controller(_ controller: MTRDeviceController, commissioningComplete error: Error?, nodeID: NSNumber?) {
        if error != nil {
            os_log(.error, "TrinhVM: commissioningComplete error -> \(error!.localizedDescription)")
        } else {
            os_log(.error, "TrinhVM: commissioningComplete ->\(nodeID)")
            if MTRGetConnectedDevice({ (chipDevice, error) in
                if chipDevice == nil {
                    os_log(.debug, "Status: Failed to establish a connection with the device")
                } else {
                    os_log(.error, "Status: Success to establish a connection with the device: \(chipDevice?.description ?? "")")
                }
            }) {
                print("Status: Waiting for connection with the device")
            } else {
                print("Status: Failed to trigger the connection with the device")
            }
        }
}
