public:
    class EthernetNetworkIterator final : public NetworkIterator
    {
    public:
        EthernetNetworkIterator(ZephyrEthernetDriver * aDriver) : mDriver(aDriver) {};
        ~EthernetNetworkIterator() override = default;
        
        size_t Count() override { return 1; }
        bool Next(Network & item) override
        {
            if (exhausted)
            {
                return false;
            }
            exhausted = true;
            memcpy(item.networkID, interfaceName, interfaceNameLen);
            item.networkIDLen = interfaceNameLen;
            item.connected    = true;
            return true;
        }
        void Release() override { delete this; }

        uint8_t interfaceName[kMaxNetworkIDLen];
        uint8_t interfaceNameLen = 0;
        bool exhausted           = false;

    private:
        ZephyrEthernetDriver * mDriver;
    };

    uint8_t GetMaxNetworks() override { return 1; }
    NetworkIterator * GetNetworks() override { return new EthernetNetworkIterator(this); }

    CHIP_ERROR Init(NetworkStatusChangeCallback * networkStatusChangeCallback) override;

    static ZephyrEthernetDriver & GetInstance()
    {
        static ZephyrEthernetDriver instance;
        return instance;
    }
};

