### Reproduction steps

I defined a SendOnOffCommand() function to send a switch command, and then called the OnDeviceConnected() function when the connection was successful. The SendOnOffCommand() function was called again, but when I pressed the send button, this function executed both sides. , causing the status of my light fixture to change from on to off, and then back to on again, why is this.
Below is my code and logging for these two functions:
CHIP_ERROR SendOnOffCommand(chip::Messaging::ExchangeManager &exchangeMgr, const chip::SessionHandle &sessionHandle, const std::vector<uint16_t> &endpointIds, bool on)
{
    CHIP_ERROR chip_err = CHIP_NO_ERROR;

    for (auto endpointId : endpointIds)
    {
        // 创建 CommandSender 回调对象
        auto *callback = new CommandSenderCallback();
        if (!callback)
        {
            ESP_LOGE(TAG, "分配 CommandSenderCallback 失败");
            return CHIP_ERROR_NO_MEMORY;
        }

        // 创建 CommandSender 对象
        auto *commandSender = new chip::app::CommandSender(callback, &exchangeMgr);
        if (!commandSender)
        {
            ESP_LOGE(TAG, "创建 CommandSender 失败");
            delete callback;
            return CHIP_ERROR_NO_MEMORY;
        }

        ESP_LOGI(TAG, "准备发送命令: %s 到 endpoint %d", on ? "打开" : "关闭", endpointId);

        // 设置命令路径
        chip::app::CommandPathParams cmdPath(
            endpointId,                                        // 设备的 Endpoint ID
            0,                                                 // Group ID (0 表示单播)
            chip::app::Clusters::OnOff::Id,                    // Cluster ID（比如 On/Off Cluster）
            on ? chip::app::Clusters::OnOff::Commands::On::Id  // 要发送的命令 ID
               : chip::app::Clusters::OnOff::Commands::Off::Id,
            chip::app::CommandPathFlags::kEndpointIdValid      // 表示 Endpoint ID 有效的标志
        );

        ESP_LOGI(TAG, "命令路径信息: endpointId: %d, ClusterId: %lu, CommandId: %lu",
                 cmdPath.mEndpointId,
                 static_cast<unsigned long>(cmdPath.mClusterId),
                 static_cast<unsigned long>(cmdPath.mCommandId));

        // 装配控制命令
        chip::app::CommandSender::AddRequestDataParameters addDataParams;
        if (on)
        {
            chip::app::Clusters::OnOff::Commands::On::Type onCommand;
            chip_err = commandSender->AddRequestData(cmdPath, onCommand, addDataParams);
            ESP_LOGI(TAG, "发送打开命令: endpointId: %u, ClusterId: %lu, CommandId: %lu", cmdPath.mEndpointId, static_cast<unsigned long>(cmdPath.mClusterId), static_cast<unsigned long>(cmdPath.mCommandId));
        }
        else
        {
            chip::app::Clusters::OnOff::Commands::Off::Type offCommand;
            chip_err = commandSender->AddRequestData(cmdPath, offCommand, addDataParams);
            ESP_LOGI(TAG, "发送关闭命令: endpointId: %u, ClusterId: %lu, CommandId: %lu", cmdPath.mEndpointId, static_cast<unsigned long>(cmdPath.mClusterId), static_cast<unsigned long>(cmdPath.mCommandId));
        }

        if (chip_err != CHIP_NO_ERROR)
        {
            ESP_LOGE(TAG, "AddRequestData 失败，错误码: %s", chip::ErrorStr(chip_err));
            delete commandSender;
            delete callback;
            return chip_err;
        }

        ESP_LOGI(TAG, "当前可用堆内存: %lu bytes", esp_get_free_heap_size());

        // 发送命令请求
        chip_err = commandSender->SendCommandRequest(sessionHandle);
        if (chip_err != CHIP_NO_ERROR)
        {
            ESP_LOGE(TAG, "SendCommandRequest 失败: %s", chip::ErrorStr(chip_err));
            delete commandSender;
            delete callback;
            return chip_err;
        }

        ESP_LOGI(TAG, "命令已成功发送到 endpoint %d", endpointId);
        
        // CommandSender 和 callback 对象的清理将由 CommandSenderCallback 完成
    }

    return CHIP_NO_ERROR;
}


// 连接成功处理
void OnDeviceConnected(void* context, chip::Messaging::ExchangeManager& exchangeMgr, const chip::SessionHandle& sessionHandle)
{
    chip::ScopedNodeId peerId = sessionHandle->GetPeer();
    chip::NodeId nodeId = peerId.GetNodeId();
    ESP_LOGI(TAG, "成功与设备建立会话: Node ID 0x%llX", nodeId);

    // 检查是否在灯具表中
    if (lightStateTable.find(nodeId) != lightStateTable.end()) {
        LightState &light = lightStateTable[nodeId];

        // 准备 endpoint 列表
        std::vector<uint16_t> endpointIds = {light_endpoint_id_1, light_endpoint_id_2};

        if (currentCommandType == COMMAND_ON_OFF) {
            // 切换灯具 A 和 B 的开关状态
            bool new_on_off_state = !light.lightA.isOn;

            ESP_LOGI(TAG, "节点ID 0x%llX 的灯具 A 和 B 开关状态准备变换为: %d", nodeId, new_on_off_state);

            // 发送单一命令同时控制 A 和 B
            CHIP_ERROR chip_err = SendOnOffCommand(exchangeMgr, sessionHandle, endpointIds, new_on_off_state);
            if (chip_err == CHIP_NO_ERROR) {
                // 更新状态表
                light.lightA.isOn = new_on_off_state;
                light.lightB.isOn = new_on_off_state;
                ESP_LOGI(TAG, "成功发送开关命令到灯具 A 和 B，Node ID: 0x%llX", nodeId);
                UpdateLightState(nodeId, new_on_off_state, light.lightA.brightness, new_on_off_state, light.lightB.brightness);
            } else {
                ESP_LOGE(TAG, "发送灯具 A 和 B 控制命令失败: %s", chip::ErrorStr(chip_err));
            }
        } else if (currentCommandType == COMMAND_DIMMING) {
            // 发送调光命令到两个灯具的 endpoint
            CHIP_ERROR chip_err = SendDimmingCommand(exchangeMgr, sessionHandle, endpointIds, target_brightness);
            if (chip_err == CHIP_NO_ERROR) {
                light.lightA.brightness = target_brightness;
                light.lightB.brightness = target_brightness;
                ESP_LOGI(TAG, "成功发送调光命令到灯具 A 和 B，Node ID: 0x%llX", nodeId);
                UpdateLightState(nodeId, light.lightA.isOn, target_brightness, light.lightB.isOn, target_brightness);
            } else {
                ESP_LOGE(TAG, "发送灯具 A 和 B 调光命令失败: %s", chip::ErrorStr(chip_err));
            }
        }
    } else {
        ESP_LOGE(TAG, "节点ID 0x%llX 不在灯具表中", nodeId);
    }

    // 更新本地属性状态（同步本地状态）
    esp_err_t esp_err = client::cluster_update(switch_endpoint_id, &req_handle);
    if (esp_err != ESP_OK) {
        ESP_LOGE(TAG, "更新本地属性状态失败: %s", esp_err_to_name(esp_err));
    }

    esp_matter_attr_val_t on_off_val = esp_matter_bool(current_on_off_state);
    esp_err_t err2 = attribute::update(switch_endpoint_id, OnOff::Id, OnOff::Attributes::OnOff::Id, &on_off_val);
    if (err2 != ESP_OK) {
        ESP_LOGE(TAG, "无法设置 OnOff 属性值: %s", esp_err_to_name(err2));
    }
}
