Structure encode/decode is currently generated by `cluster-objects-src.zapt` which generates one large encode/decode structure like:

```cpp
CHIP_ERROR Type::Encode(TLV::TLVWriter & aWriter, TLV::Tag aTag) const
{
    TLV::TLVType outer;

    ReturnErrorOnFailure(aWriter.StartContainer(aTag, TLV::kTLVType_Structure, outer));
    ReturnErrorOnFailure(DataModel::Encode(aWriter, TLV::ContextTag(Fields::kActive), active));
    ReturnErrorOnFailure(DataModel::Encode(aWriter, TLV::ContextTag(Fields::kInactive), inactive));
    ReturnErrorOnFailure(DataModel::Encode(aWriter, TLV::ContextTag(Fields::kState), state));
    ReturnErrorOnFailure(DataModel::Encode(aWriter, TLV::ContextTag(Fields::kMask), mask));
    return aWriter.EndContainer(outer);
}

CHIP_ERROR DecodableType::Decode(TLV::TLVReader & reader)
{
    detail::StructDecodeIterator __iterator(reader);
    while (true)
    {
        auto __element = __iterator.Next();
        if (std::holds_alternative<CHIP_ERROR>(__element))
        {
            return std::get<CHIP_ERROR>(__element);
        }
        CHIP_ERROR err              = CHIP_NO_ERROR;

        const uint8_t __context_tag = std::get<uint8_t>(__element);
        if (__context_tag == to_underlying(Fields::kActive))
        {
            err = DataModel::Decode(reader, active);
        }
        else if (__context_tag == to_underlying(Fields::kInactive))
        {
            err = DataModel::Decode(reader, inactive);
        }
        else if (__context_tag == to_underlying(Fields::kState))
        {
            err = DataModel::Decode(reader, state);
        }
        else if (__context_tag == to_underlying(Fields::kMask))
        {
            err = DataModel::Decode(reader, mask);
        }
        else
        {
        }
        ReturnErrorOnFailure(err);
    }
}
```

Investigate if we could convert this logic to a shared logic of table-driven design (where table is optimized for size, likely using varints or similar) so that we gain:
   - code size improvement - assumption is that tables + code for table-driven decoder is smaller than several code-driven decoders as encode and decode share a single table (savings increase as more decodes are needed). This has to be prototyped first.
   - unit testability
   - separation (we could separate out per cluster instead of a large `all encode/decode`)

