    auto it = lightStateTable.find(currentNodeId);
    if (it != lightStateTable.end()) {
        LightState &light = it->second;

        // 设置开关状态
        if (light.lightA.isOn || light.lightB.isOn) {
            oledstate = "State:Open";
        } else {
            oledstate = "State:Close";
        }

        // 分别显示两盏灯的亮度
        snprintf(oledvalue, sizeof(oledvalue), "Yellow:%d Blue:%d",
                 light.lightA.brightness, light.lightB.brightness);
    } else {
        // 当前节点不在状态表中，设置为未知
        oledstate = "State:Unknown";
        snprintf(oledvalue, sizeof(oledvalue), "Yellow:N/A Blue:N/A");
    }

    // 日志调试信息
    ESP_LOGI("OLED_DEBUG", "刷新数据: Addr=%s, State=%s, Mode=%s, Value=%s", oledaddr, oledstate, oledmode, oledvalue);

    // 刷新显示
    oled_refresh(oledaddr, oledstate, oledmode, oledvalue);
}
void oled_refresh(char* addr, char* state, char* mode, char* value) {
    ESP_LOGI("OLED_REFRESH", "刷新参数: Addr=%s, State=%s, Mode=%s, Value=%s", addr, state, mode, value);

    ESP_LOGI("OLED_REFRESH", "清屏操作开始");
    OLEDDisplay_clear(oled);

    ESP_LOGI("OLED_REFRESH", "设置文本对齐和字体");
    OLEDDisplay_setTextAlignment(oled, TEXT_ALIGN_CENTER);
    OLEDDisplay_setFont(oled, ArialMT_Plain_16);

    ESP_LOGI("OLED_REFRESH", "绘制地址: %s", addr);
    OLEDDisplay_drawString(oled, 64, 0, addr);

    ESP_LOGI("OLED_REFRESH", "绘制状态: %s", state);
    OLEDDisplay_drawString(oled, 64, 15, state);

    ESP_LOGI("OLED_REFRESH", "绘制模式: %s", mode);
    OLEDDisplay_drawString(oled, 64, 30, mode);

    ESP_LOGI("OLED_REFRESH", "绘制值: %s", value);
    OLEDDisplay_drawString(oled, 64, 45, value);

    ESP_LOGI("OLED_REFRESH", "调用 OLEDDisplay_display 刷新屏幕");
    OLEDDisplay_display(oled);  // 刷新屏幕
    vTaskDelay(pdMS_TO_TICKS(10));  // 确保显示稳定
    ESP_LOGI("OLED_REFRESH", "屏幕刷新完成");
}



### Bug prevalence

Once or twice a week

### GitHub hash of the SDK that was being used

5.0.2

### Platform

esp32

### Platform Version(s)

_No response_

### Type

Security Issue

### Anything else?

_No response_

### Reproduction steps

## Issue
Segmentation fault occurs when attempting to write messages to a WebSocket connection that has been closed or destroyed.

## Root Cause Analysis
The crash occurs in `lws_callback_on_writable()` when `gWebSocketInstance` is NULL, which happens when trying to write messages after a client disconnection.

### Stack Trace

```
Program terminated with signal SIGSEGV, Segmentation fault.
#0  0x00005f46f48fc5d6 in lws_callback_on_writable (wsi=0x0)
```

### Problematic Code Path

1. In `WebSocketServer.cpp`, messages are queued using the `Send()` method:
```
void WebSocketServer::Send(const char * msg)
{
    std::lock_guard<std::mutex> lock(gMutex);
    gMessageQueue.push_back(msg);
}
```



2. The main server loop attempts to process queued messages without checking connection state:
```
while (mRunning)
{
    lws_service(context, -1);

    std::lock_guard<std::mutex> lock(gMutex);
    if (gMessageQueue.size())
    {
        lws_callback_on_writable(gWebSocketInstance);  // Crashes here if gWebSocketInstance is null
    }
}
```

3. The WebSocket instance pointer is managed in callback handlers:

```
else if (LWS_CALLBACK_ESTABLISHED == reason)
{
    gWebSocketInstance = wsi;
}
else if (LWS_CALLBACK_WSI_DESTROY == reason)
{
    gWebSocketInstance = nullptr;
}
```

### Impact

Application crashes when attempting to send messages after client disconnection
Messages in queue become stale and may cause crashes when new connections are established

### Recommended Fix
Add connection state validation before attempting to write:
```
while (mRunning)
{
    lws_service(context, -1);

    std::lock_guard<std::mutex> lock(gMutex);
    if (gMessageQueue.size() && gWebSocketInstance != nullptr)
    {
        lws_callback_on_writable(gWebSocketInstance);
    }
}
```
Additionally, clean up the message queue on connection termination:
```
else if (LWS_CALLBACK_WSI_DESTROY == reason)
{
    std::lock_guard<std::mutex> lock(gMutex);
    gWebSocketInstance = nullptr;
    gMessageQueue.clear();  // Prevent stale messages from causing issues
}
```

## Test Cases

- Normal message sending with connected client
- Client disconnection while messages are in queue
- Message queuing during no active connection
- Reconnection handling with existing message queue

## Related Files

- WebSocketServer.cpp
- InteractiveCommands.cpp (caller of WebSocket server)
- [core.chip-tool.zip](https://github.com/user-attachments/files/18003897/core.chip-tool.zip)
- [Crash_WebSocketServer_lws_callback_on_writable.zip](https://github.com/user-attachments/files/18003908/Crash_WebSocketServer_lws_callback_on_writable.zip)


