[2025-08-12T15:30:56Z] user_01255: From the talks we had I designed the following interfaces:


The requests where:

A simplified Attribute Storage that is typesafe but doesn't explode with templates.
Not using any dynamic memory;
Not adding a lot of codesize;
Replace Old Interfaces, both SafeAttributeStorage.


This is the design I ended in:

## Basic Interfaces:

```
class AttributeStorage {
    CHIP_ERROR WriteValue(Key key, Encoder&) = 0; 
    CHIP_ERROR ReadValue(Key key,  Decoder&) = 0;
}

// 
struct Decoder {
    virtual MutableByteSpan GetDecodingBuffer(int size_hint = -1) = 0;

    virtual CHIP_ERROR Decode(int amount) = 0;

    virtual Decoder() {};
}

struct Encoder {
    virtual ByteSpan GetEncoded() = 0;
    virtual Encoder();
}

```


This allows us to implement methods such as

```
struct InlineEncoderDecoder : Decoder, Encoder {
    template<class T>
    InlineEncoderDecoder(T& value)  : span_(reinterpret_cast<char*>(&value), sizeof(T)) {}

    //
    ByteSpan GetEncoded() override {return span_;};
    MutableByteSpan GetDecodingBuffer() override {return span_;};
    CHIP_ERROR Decode(int amount) override {};

private:
  MutableByteSpan span_;
}
```


An example of a harder decoder;
```
struct StdStringDecoder : Decoder {

    StdStringDecoder(std::string& str) : receptor(str) {
        str.clear();
    }

    MutableByteSpan GetDecodingBuffer(int size_hint = -1) override { 
        if(size_hint > 0) receptor.resize(size_hint);
        return buffer;
    };

    CHIP_ERROR Decode(int amount) override {
        receptor += std::string_view(buffer, amount);
    };

private:
    std::string& receptor;
    char buffer[25];
}


class TestAttributeStorage : AttributeStorage {


}




int myValue;

std::string astring;
InlineEncoderDecoder encoder (myValue);

StdStringDecoder sencoder(astring);

TestAttributeStorage storage;
storage.ReadValue(key, encoder);
storage.WriteValue(key, encoder);

storage.ReadValue(key, sencoder);
storage.WriteValue(key, sencoder);

```


