[2025-06-10T11:32:20Z] user_00220: Hi @user_00012  Can you please help me to set the right conditions for kBle, kUdp, kTcp and kWiFiPAF? See the code below.

@user_01397 If you want to do a change to get RemoteId considered n this comparison, please tell me the lines to change (this is related to the Issue #39349)

```
    bool operator==(const PeerAddress & other) const
    {
        // Compare common fields
        if (mTransportType != other.mTransportType)
        {
            return false;
        }

        // Compare transport-type-specific fields
        switch (mTransportType)
        {
            case Type::kNfc:
                return (mId.mNFCShortId == other.mId.mNFCShortId);

            case Type::kBle:
            case Type::kUdp:
            case Type::kTcp:
            case Type::kWiFiPAF:
                // TODO: mId.mRemoteId is currently not considered
                return (mTransportType == other.mTransportType &&
                        mIPAddress == other.mIPAddress &&
                        mPort == other.mPort &&
                        mInterface == other.mInterface);

            default:
                // For transport types with no additional fields to compare
                return true;
        }
    }
