The problem is that [this](https://github.com/project-chip/connectedhomeip/blob/97149006d64cad95bb997df8b068a2d70ad159b3/examples/camera-app/linux/src/clusters/webrtc-provider/webrtc-provider-manager.cpp#L649) should never work with current controller's [invoke API](https://github.com/project-chip/connectedhomeip/blob/97149006d64cad95bb997df8b068a2d70ad159b3/src/controller/InvokeInteraction.h#L151) since that constructs a [CommandSender](https://github.com/project-chip/connectedhomeip/blob/97149006d64cad95bb997df8b068a2d70ad159b3/src/controller/InvokeInteraction.h#L85) without specification of `AllowLargePayload` arg that'd default to false, and therefore none of the async SDP answers, ICE candidates or end commands would reach back to the controller against the SDP offer and other commands.

The fix I think is to propagate that parameter (might need feedback on API definiton since it's getting at the point of a lot of confusing optional args at the end):

```diff
diff --git a/src/controller/InvokeInteraction.h b/src/controller/InvokeInteraction.h
index 7576f8aac2..e540b78a72 100644
--- a/src/controller/InvokeInteraction.h
+++ b/src/controller/InvokeInteraction.h
@@ -56,7 +56,7 @@ InvokeCommandRequest(Messaging::ExchangeManager * aExchangeMgr, const SessionHan
                      typename TypedCommandCallback<typename RequestObjectT::ResponseType>::OnErrorCallbackType onErrorCb,
                      const Optional<uint16_t> & timedInvokeTimeoutMs,
                      const Optional<System::Clock::Timeout> & responseTimeout = NullOptional,
-                     Internal::InvokeCancelFn * outCancelFn                   = nullptr)
+                     Internal::InvokeCancelFn * outCancelFn = nullptr, bool allowLargePayload = false)
 {
     // InvokeCommandRequest expects responses, so cannot happen over a group session.
     VerifyOrReturnError(!sessionHandle->IsGroupSession(), CHIP_ERROR_INVALID_ARGUMENT);
@@ -81,8 +81,8 @@ InvokeCommandRequest(Messaging::ExchangeManager * aExchangeMgr, const SessionHan

     decoder->SetOnDoneCallback(onDone);

-    auto commandSender =
-        chip::Platform::MakeUnique<app::CommandSender>(decoder.get(), aExchangeMgr, timedInvokeTimeoutMs.HasValue());
+    auto commandSender = chip::Platform::MakeUnique<app::CommandSender>(
+        decoder.get(), aExchangeMgr, timedInvokeTimeoutMs.HasValue(), false /* Suppress Response */, allowLargePayload);
     VerifyOrReturnError(commandSender != nullptr, CHIP_ERROR_NO_MEMORY);

     ReturnErrorOnFailure(commandSender->AddRequestData(commandPath, requestCommandData, timedInvokeTimeoutMs));
```

And then usage in webrtc manager:
```diff
diff --git a/examples/camera-app/linux/src/clusters/webrtc-provider/webrtc-provider-manager.cpp b/examples/camera-app/linux/src/clusters/webrtc-provider/webrtc-provider-manager.cpp
index 9f61746daa..01943b3bfc 100644
--- a/examples/camera-app/linux/src/clusters/webrtc-provider/webrtc-provider-manager.cpp
+++ b/examples/camera-app/linux/src/clusters/webrtc-provider/webrtc-provider-manager.cpp

@@ -571,7 +585,8 @@ CHIP_ERROR WebRTCProviderManager::SendOfferCommand(Messaging::ExchangeManager &
     command.sdp             = CharSpan::fromCharString(mLocalSdp.c_str());

     // Now invoke the command using the found session handle
-    return Controller::InvokeCommandRequest(&exchangeMgr, sessionHandle, mOriginatingEndpointId, command, onSuccess, onFailure);
+    return Controller::InvokeCommandRequest(&exchangeMgr, sessionHandle, mOriginatingEndpointId, command, onSuccess, onFailure,
+                                            NullOptional, NullOptional, nullptr, true);
 }

 void WebRTCProviderManager::OnLocalDescription(const std::string & sdp, SDPType type)
@@ -646,7 +661,8 @@ CHIP_ERROR WebRTCProviderManager::SendAnswerCommand(Messaging::ExchangeManager &
     command.sdp             = CharSpan::fromCharString(mLocalSdp.c_str());

     // Now invoke the command using the found session handle
-    return Controller::InvokeCommandRequest(&exchangeMgr, sessionHandle, mOriginatingEndpointId, command, onSuccess, onFailure);
+    return Controller::InvokeCommandRequest(&exchangeMgr, sessionHandle, mOriginatingEndpointId, command, onSuccess, onFailure,
+                                            NullOptional, NullOptional, nullptr, true);
 }

 CHIP_ERROR WebRTCProviderManager::SendICECandidatesCommand(Messaging::ExchangeManager & exchangeMgr,
@@ -680,7 +696,8 @@ CHIP_ERROR WebRTCProviderManager::SendICECandidatesCommand(Messaging::ExchangeMa
     command.ICECandidates = DataModel::List<const ICECandidateStruct>(iceCandidateStructList.data(), iceCandidateStructList.size());

     // Now invoke the command using the found session handle
-    return Controller::InvokeCommandRequest(&exchangeMgr, sessionHandle, mOriginatingEndpointId, command, onSuccess, onFailure);
+    return Controller::InvokeCommandRequest(&exchangeMgr, sessionHandle, mOriginatingEndpointId, command, onSuccess, onFailure,
+                                            NullOptional, NullOptional, nullptr, true);
 }
```

