[2025-11-26T17:55:45Z] user_00224: Was chatting with @tennessee-google about this & think I may have come up with something which would allow us to choose at compile-time, thus allowing for flash-savings in environments where we want to just die, while handling the failure when we don't:

```
class [[nodiscard]] CriticalFailure {
#ifdef CALLER_HANDLES_CRITICAL_FAILURE
   CHIP_ERROR error;
public:
   CriticalFailure(CHIP_ERROR err) : error(err) {}

  template <class F>
  __attribute__((always_inline)) inline bool Handle(F && fn)
  {
        if (!::chip::ChipError::IsSuccess(error)) {
          fn(error);
          return false;
        }
        return true;
  }
}
#else
public:
   CriticalFailure(CHIP_ERROR err) { SuccessOrDie(err); }

  template <class F>
  __attribute__((always_inline)) inline bool Handle(F && fn)
  { return true; }
#endif

CriticalFailure MemoryInit();

void Example() {
   VerifyOrReturn(MemoryInit().Handle( [&](auto error) {
        ChipLogFailure(error, Controller, "Failed to initialize memory");  
   }));
}
```

In the cases where `CALLER_HANDLES_CRITICAL_FAILURE` is defined,  it'll behave similarly to a `CHIP_ERROR`. Otherwise, a failure will cause the process to die & the `handle` branch should be optimized away

