    const chip::Logging::LogCategory &inLogCategory
) noexcept
{
    ...
}

static void
MatterLogRedirectCallback(
    const char *inModule,
    uint8_t inCategory,
    const char *inMessage,
    va_list inArguments
) noexcept
{
    ...
}

}; // namespace Detail

// MARK: Function and Method Implementation

// MARK: My Daemon Matter Controller

// MARK: Initialization

status_t
Controller :: Init(void) noexcept
{
    // The controller can be provisioned either over BLE or on-network.

    static constexpr chip::RendezvousInformationFlags kRendezvousInformationFlags = {
        chip::RendezvousInformationFlag::kBLE,
        chip::RendezvousInformationFlag::kOnNetwork
    };

    CHIP_ERROR                                        lStatus;
    status_t                                          lRetval                     = MY_STATUS_SUCCESS;

    // Set the logging redirect callback such that we can redirect
    // from the default C Standard Output output to the current
    // process log stream.

    chip::Logging::SetLogRedirectCallback(Detail::MatterLogRedirectCallback);

    // Initialize the Matter dynamic memory allocation subsystem.

    lStatus = chip::Platform::MemoryInit();
    nlREQUIRE_ACTION(lStatus == CHIP_NO_ERROR, done, lRetval = FWDS_ERROR_UNKNOWN);

    // Initialize the Matter device layer platform manager.

    lStatus = chip::DeviceLayer::PlatformMgr().InitChipStack();
    nlREQUIRE_ACTION(lStatus == CHIP_NO_ERROR, done, lRetval = FWDS_ERROR_UNKNOWN);

    // Set the provider for commissionable data (that is, a set of
    // data for commissioning that includes the setup discriminiator;
    // SPAKE2+ iteration count, salt, and verifier; and setup code).
    //
    // For now, allocate and use a test-only instance.

    mCommissionableDataProvider.reset(new (std::nothrow) chip::DeviceLayer::TestOnlyCommissionableDataProvider);
    nlREQUIRE_ACTION(mCommissionableDataProvider != nullptr, done, lRetval = -EINVAL);

    chip::DeviceLayer::SetCommissionableDataProvider(mCommissionableDataProvider.get());

    // Set the provider for the device instance information (that
    // is, vendor name, vendor identifier, product name, product
    // identifier, part number, product label, product URL, serial
    // number, manufacturing date, hardware version, hardware version
    // string, rotating device unique identifier, product finish, and
    // product primary color).
    //
    // For now, just use the default singleton instance provided by
    // DeviceInstanceInfoProviderMgrImpl().

#if !defined(MY_MATTER_PROTOTYPE) || (MY_MATTER_PROTOTYPE != 1)
    chip::DeviceLayer::SetDeviceInstanceInfoProvider();
#endif // !defined(MY_MATTER_PROTOTYPE) || (MY_MATTER_PROTOTYPE != 1)

    // Set the provider for the Device Attestation Credentials (that
    // is, certification declaration, firmware information, device
    // attestation certificate (DAC), product attestation intermediate
    // (PAI) certificate, and device attestation signing).
    //
    // For now, just use the Matter credentials example provider.

    chip::Credentials::SetDeviceAttestationCredentialsProvider(chip::Credentials::Examples::GetExampleDACProvider());

    // Log the device configuration.

    chip::DeviceLayer::ConfigurationMgr().LogDeviceConfig();

    // Log the provisioning QRCode URL and short, manual pairing code,
    // based on the allowed rendezvous information flags.
    //
    // This uses the commissionable data provider set above to pull
    // the relevant commissionable data necessary to build the QRCode
    // and get the short, manual pairing code.

    PrintOnboardingCodes(kRendezvousInformationFlags);

 done:
    return (lRetval);
}

status_t
Controller :: Shutdown(void) noexcept
{
    status_t   lRetval = MY_STATUS_SUCCESS;

    // Shutdown the Matter device layer platform manager.

    chip::DeviceLayer::PlatformMgr().Shutdown();

    // Shutdown the Matter dynamic memory allocation subsystem.

    chip::Platform::MemoryShutdown();

    // Reset the logging redirect callback.

    chip::Logging::SetLogRedirectCallback(nullptr);

    return (lRetval);
}
